// Normaliza el identificador: email, teléfono o cédula.
// Sólo se busca por teléfono/cédula cuando hay al menos 6 dígitos, para evitar
// coincidencias accidentales con valores muy cortos.
const body = $input.first().json.body || $input.first().json || {};
const raw = String(body.identifier || '').trim();

if (!raw) {
  return [{ json: { __error: true, statusCode: 400, message: 'identifier is required' } }];
}

const digits = raw.replace(/\D/g, '');

return [{ json: {
  identifier: raw,
  email_candidate: raw.toLowerCase(),
  digits_candidate: digits.length >= 6 ? digits : '__no_match__',
  supplied_email: String(body.email || '').trim().toLowerCase(),
} }];

// Valida el código contra el hash guardado, la expiración y los intentos.
const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const user = rows[0];
const body = $('Webhook').first().json.body || {};
const code = String(body.code || '').trim();

if (!user) {
  return [{ json: { __respond: true, statusCode: 404, body: { message: 'No encontramos ese paciente.' } } }];
}
if (!user.login_code || !user.login_code_expires_at) {
  return [{ json: { __respond: true, statusCode: 410, body: { message: 'Pedí un código nuevo.' } } }];
}
if (new Date(user.login_code_expires_at).getTime() < Date.now()) {
  return [{ json: { __respond: true, statusCode: 410, body: { message: 'El código venció. Pedí uno nuevo.' } } }];
}
if (Number(user.login_code_attempts || 0) >= 5) {
  return [{ json: { __respond: true, statusCode: 429, body: { message: 'Demasiados intentos. Pedí un código nuevo.' } } }];
}

const crypto = require('crypto');
const hash = crypto.createHash('sha256').update(code + String(user.id)).digest('hex');

if (hash !== user.login_code) {
  return [{ json: { __respond: false, __invalid: true, user_id: user.id,
                    statusCode: 401, body: { message: 'El código no es correcto.' } } }];
}

// is_new: registrado hace menos de 30 min y sin haber entrado nunca al portal.
const createdAt = user.created_at ? new Date(user.created_at).getTime() : 0;
const isNew = !user.is_portal_user && createdAt > Date.now() - 30 * 60 * 1000;

return [{ json: {
  __respond: false, __invalid: false,
  user_id: user.id, name: user.name, email: user.email, is_new: isNew,
} }];

// Claims EXACTAMENTE como los emite /api/auth/login. Verificado decodificando un
// token real del sistema:
//   { "userId": "<uuid>", "email": "...", "expiresIn": "24h", "iat": <epoch> }
//
// Ojo con lo que NO lleva:
//   · No hay `sub`  → el identificador del usuario va en `userId`.
//   · No hay `roles`→ /auth/me los resuelve consultando user_roles en la BD.
//   · No hay `exp`  → "expiresIn" es un claim literal, no la opción de jsonwebtoken.
// `iat` lo agrega solo el nodo JWT al firmar.
const ctx = $('Validar Código').first().json;

return [{ json: {
  userId: ctx.user_id,
  email: ctx.email,
  expiresIn: '24h',
} }];

// El nodo JWT devuelve { token }. El usuario sale del paso de validación —
// deliberadamente NO se devuelve users.password ni ningún otro campo interno.
const ctx = $('Validar Código').first().json;
const token = $input.first().json.token;

if (!token) {
  return [{ json: { statusCode: 500, body: { message: 'No se pudo emitir el token de acceso.' } } }];
}

return [{ json: { statusCode: 200, body: {
  token,
  user: { id: ctx.user_id, name: ctx.name, email: ctx.email },
  is_new: ctx.is_new === true,
} } }];
